  fp.init(
    browsingContext,
    lazy.bundle.GetStringFromName("ChooseFolder"),
    Ci.nsIFilePicker.modeGetFolder
  );
  try {
    fp.displayDirectory = Services.prefs.getComplexValue(
      "messenger.save.dir",
      Ci.nsIFile
    );
  } catch (e) {} // Pref may not be set, yet.

